'use strict';
const assert=require('node:assert/strict');
const{createHash}=require('node:crypto');
const fs=require('node:fs/promises');
const path=require('node:path');
const Scenario=require('./secureshopV03RenderedScenario');
const SHA=/^[a-f0-9]{64}$/,UUID=/^[a-f0-9]{8}-[a-f0-9]{4}-[1-5][a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$/i;
const hash=bytes=>createHash('sha256').update(bytes).digest('hex');
function describeError(error,depth=0){if(!error||depth>3)return null;const value={name:String(error.name||'Error').slice(0,80),code:typeof error.code==='string'?error.code.slice(0,120):null,message:String(error.message||'').slice(0,1000),stack:typeof error.stack==='string'?error.stack.slice(0,4000):null};for(const key of['v03Stage','roleChoiceStage'])if(typeof error[key]==='string')value[key]=error[key].slice(0,160);const diagnostic=error.v03RequestDiagnostic;if(diagnostic&&Object.getPrototypeOf(diagnostic)===Object.prototype&&Object.keys(diagnostic).sort().join(',')==='choiceId,requestId,responseCode,responseError,sessionId,state,status,version'&&diagnostic.version===1&&['armed','submitted','accepted'].includes(diagnostic.state)&&['sessionId','requestId','choiceId'].every(key=>diagnostic[key]===null||UUID.test(diagnostic[key]))&&(diagnostic.status===null||Number.isSafeInteger(diagnostic.status)&&diagnostic.status>=100&&diagnostic.status<=599)&&(diagnostic.responseCode===null||typeof diagnostic.responseCode==='string'&&diagnostic.responseCode.length<=120)&&(diagnostic.responseError===null||typeof diagnostic.responseError==='string'&&diagnostic.responseError.length<=240))value.v03RequestDiagnostic=structuredClone(diagnostic);if(Array.isArray(error.errors))value.errors=error.errors.slice(0,8).map(item=>describeError(item,depth+1));if(error.cause)value.cause=describeError(error.cause,depth+1);return value;}
const STATIC_HASH_KEYS=Object.freeze(['sourceManifestSha256','frontendInventorySha256','browserSha256','modelManifestSha256','nativeReceiptSha256']);
async function readPinnedArtifacts({paths,pins}){assert.deepEqual(Object.keys(paths).sort(),[...STATIC_HASH_KEYS].sort());assert.deepEqual(Object.keys(pins).sort(),[...STATIC_HASH_KEYS].sort());const observed={};for(const key of STATIC_HASH_KEYS){assert.match(pins[key],SHA);observed[key]=hash(await fs.readFile(path.resolve(paths[key])));assert.equal(observed[key],pins[key],key);}return Object.freeze(observed);}
function actorSpansFor({invocations,wires,phase}){const spans=invocations.filter(row=>row.phase===phase);assert.deepEqual(spans.map(row=>row.method),['chat','finalResponse']);assert.ok(spans[0].wireStart>=0&&spans[0].wireStart<spans[0].wireEnd&&spans[0].wireEnd<=spans[1].wireStart&&spans[1].wireStart<spans[1].wireEnd&&spans[1].wireEnd<=wires.length);return Object.freeze(spans.map(row=>structuredClone(row)));}
async function runV03ActualCaller({workspace,artifactPaths,artifactPins,originalEvidencePath,scenarioOptions,cleanup,preserveFailure,freezeOriginalEvidence,capture}={}){
 assert.equal(typeof cleanup,'function');assert.equal(typeof preserveFailure,'function');assert.equal(typeof freezeOriginalEvidence,'function');let scenario,failure,cleanupProof,preservedFailure;
 try{assert.ok(capture&&Array.isArray(capture.wires)&&Array.isArray(capture.invocations));const hashes=await readPinnedArtifacts({paths:artifactPaths,pins:artifactPins});const originalRead=scenarioOptions.readOriginalEvidence;assert.equal(typeof originalRead,'function');scenario=await Scenario.qualifyV03RenderedScenario({...scenarioOptions,hashes,readOriginalEvidence:async item=>{const phase=item.c.phase;assert.ok(['vulnerable','benign','fixed'].includes(phase));return originalRead(item,{wireCalls:capture.wires,roleActorSpans:actorSpansFor({invocations:capture.invocations,wires:capture.wires,phase:`${phase}:role`}),listingActorSpans:actorSpansFor({invocations:capture.invocations,wires:capture.wires,phase:`${phase}:listing`})});}});await freezeOriginalEvidence({scenario,failure:null});const original=path.resolve(originalEvidencePath);assert.ok(!original.startsWith(path.resolve(workspace)+path.sep));const originalEvidenceSha256=hash(await fs.readFile(original));assert.equal(capture.originalEvidenceSha256,originalEvidenceSha256);scenario=Object.freeze({...scenario,hashes:Object.freeze({...hashes,originalEvidenceSha256})});}
 catch(error){failure=error;try{await freezeOriginalEvidence({scenario:scenario||null,failure:describeError(error)});await preserveFailure(error);preservedFailure=error;}catch(preserveError){failure=Object.assign(new AggregateError([error,preserveError],'V03 qualification failed and preservation failed'),{cause:error});}}
 finally{try{cleanupProof=await cleanup();}catch(error){if(!failure)failure=error;else failure=Object.assign(new AggregateError([failure,error],'V03 qualification and cleanup failed'),{cause:failure});}}
 if(failure&&failure!==preservedFailure)try{await preserveFailure(failure);}catch(preserveError){failure=Object.assign(new AggregateError([failure,preserveError],'V03 final failure preservation failed'),{cause:failure});}
 if(failure)throw failure;return Scenario.finalizeV03RenderedScenario(scenario,cleanupProof);
}
module.exports={STATIC_HASH_KEYS,describeError,readPinnedArtifacts,actorSpansFor,runV03ActualCaller};
